// LinkedIn — distance to the nearest supply point: multi-source BFS. 'S' supply, '#' wall, '.' open.
public static class Supply {
    // Steps from every cell to its nearest supply point (4 directions); -1 for walls and unreachable cells.
    public static int[,] Distances(string[] grid) {
        if (grid == null || grid.Length == 0) return new int[0, 0];
        int R = grid.Length, C = grid[0].Length;
        var d = new int[R, C];
        var q = new Queue<(int, int)>();
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++) {
                d[r, c] = -1;
                if (grid[r][c] == 'S') { d[r, c] = 0; q.Enqueue((r, c)); }   // every source starts at once
            }
        int[] dr = { 1, -1, 0, 0 }, dc = { 0, 0, 1, -1 };
        while (q.Count > 0) {
            var (r, c) = q.Dequeue();
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C || grid[nr][nc] == '#' || d[nr, nc] >= 0) continue;
                d[nr, nc] = d[r, c] + 1;
                q.Enqueue((nr, nc));
            }
        }
        return d;
    }

    // The farthest any open cell is from supply (0 if none reachable).
    public static int WorstCase(string[] grid) {
        var d = Distances(grid); int worst = 0;
        foreach (var x in d) worst = Math.Max(worst, x);
        return worst;
    }
}
